<template>
  <main class="smart-app">
    <header class="page-heading">
      <div><div class="eyebrow">APP 自动化 / 页面驱动</div><h1>智能 APP 自动化 <el-tag size="small" effect="plain">脚本执行</el-tag></h1><p>用页面文字和输入框描述目标，执行时读取当前页面定位。</p></div>
      <div class="heading-actions"><el-button @click="helpVisible = true">使用说明</el-button><el-button :loading="loading" @click="load">刷新</el-button></div>
    </header>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="notice" />
    <el-tabs v-model="tab">
      <el-tab-pane label="用例工作台" name="scripts">
        <div class="workspace">
          <aside class="case-rail">
            <div class="rail-title"><strong>我的用例</strong><el-button v-if="canWrite" text type="primary" @click="newScript">新建</el-button></div>
            <el-input v-model="search" placeholder="搜索用例" clearable aria-label="搜索用例" />
            <div v-if="!filteredScripts.length" class="empty-rail">还没有用例<br />先载入示例，或导入生成的脚本。</div>
            <button v-for="item in filteredScripts" :key="item.id" class="case-item" :class="{ selected: draft.id === item.id }" @click="selectScript(item)"><strong>{{ item.name }}</strong><span>{{ platformName(item.platform) }} · {{ item.steps.length }} 步</span></button>
            <div class="template-box"><span>从已验证的场景开始</span><el-button v-for="(item, i) in templates" :key="item.name" text @click="useTemplate(i)">{{ item.name.replace('完美世界电竞 · ', '') }}</el-button></div>
          </aside>
          <section class="editor">
            <div class="editor-toolbar"><strong>{{ draft.id ? '编辑用例' : '新用例' }}<span v-if="dirty" class="dirty-dot"> · 有未保存修改</span></strong><div><el-button text @click="importVisible = true">导入脚本</el-button><el-button text @click="exportScript">导出脚本</el-button><el-button v-if="draft.id" text @click="duplicate">另存副本</el-button></div></div>
            <el-form label-position="top" :disabled="!canWrite">
              <div class="case-fields"><el-form-item label="用例名称"><el-input v-model="draft.name" maxlength="120" placeholder="例如：CS 资讯评论草稿" /></el-form-item><el-form-item label="设备平台"><el-select v-model="draft.platform"><el-option label="Android" value="ANDROID" /><el-option label="iPhone / iOS" value="IOS" /><el-option label="原生鸿蒙" value="HARMONYOS" /></el-select></el-form-item></div>
              <el-form-item label="应用包名 / Bundle ID"><el-input v-model="draft.packageName" placeholder="启动应用时使用；从当前页面执行可留空" /></el-form-item>
              <div class="section-title"><h2>测试步骤</h2><span>{{ draft.steps.length }} 步 · 目标不写入元素库</span></div>
              <el-collapse v-model="expanded" accordion class="step-list">
                <el-collapse-item v-for="(step, i) in draft.steps" :key="i" :name="String(i)">
                  <template #title><div class="step-summary"><span class="step-number">{{ i + 1 }}</span><strong>{{ step.name || actionLabel(step.action) }}</strong><span class="step-target">{{ targetSummary(step) }}</span><el-tag v-if="step.effect === 'WRITE'" type="warning" size="small">业务写入</el-tag></div></template>
                  <div class="step-body"><div class="step-grid"><el-form-item label="步骤名称"><el-input v-model="step.name" placeholder="描述这一步的目的" /></el-form-item><el-form-item label="操作"><el-select v-model="step.action" @change="onActionChange(step)"><el-option v-for="(label, action) in actions" :key="action" :label="label" :value="action" /></el-select></el-form-item></div>
                    <template v-if="needsTarget(step.action)"><div class="step-grid"><el-form-item label="如何找到目标"><el-select :model-value="targetKind(step)" @change="setTargetKind(step, $event)"><el-option label="页面文字完全匹配" value="text" /><el-option label="页面文字包含" value="contains" /><el-option label="控件 ID" value="id" /><el-option label="无障碍说明" value="description" /><el-option label="当前页面输入框" value="input" /></el-select></el-form-item><el-form-item v-if="targetKind(step) !== 'input'" label="目标内容"><el-input :model-value="targetValue(step)" @update:model-value="setTargetValue(step, $event)" placeholder="例如：我的，或 ${newsTitle}" /></el-form-item><el-form-item v-else label="目标内容"><el-input model-value="读取当前页面的输入框" disabled /></el-form-item></div>
                      <div class="step-grid"><el-form-item label="位于包含文字的控件区域内（可选）"><el-input v-model="step.target!.withinText" placeholder="用于区分重复目标，需为目标的祖先或包围区域" /></el-form-item><el-form-item label="匹配序号（可选，从 0 开始）"><el-input :model-value="step.target?.index == null ? '' : String(step.target.index)" type="number" min="0" placeholder="留空要求唯一匹配" clearable @update:model-value="setTargetIndex(step, $event)" /></el-form-item></div>
                    </template>
                    <el-form-item v-if="['INPUT','ASSERT','LAUNCH'].includes(step.action)" :label="step.action === 'INPUT' ? '输入内容' : step.action === 'ASSERT' ? '预期内容（可选，完全匹配）' : '启动包名（留空使用用例包名）'"><el-input v-model="step.value" placeholder="支持 ${变量名}" /></el-form-item>
                    <el-form-item v-if="step.action === 'READ'" label="保存为变量"><el-input v-model="step.saveAs" placeholder="例如 newsTitle，后续用 ${newsTitle} 引用" /></el-form-item>
                    <el-form-item v-if="step.action === 'SWIPE'" label="滑动方向"><el-radio-group v-model="step.direction"><el-radio-button label="UP">向上滑</el-radio-button><el-radio-button label="DOWN">向下滑</el-radio-button></el-radio-group></el-form-item>
                    <div class="step-options"><el-form-item v-if="needsTarget(step.action)" label="等待目标出现（秒）"><el-input-number v-model="step.timeoutSeconds" :min="1" :max="30" /></el-form-item><el-checkbox :model-value="step.effect === 'WRITE'" @update:model-value="step.effect = $event ? 'WRITE' : 'READ'">这一步会发布或修改业务数据</el-checkbox></div>
                    <div class="step-reorder"><el-button size="small" :disabled="i === 0" @click="moveStep(i, -1)">上移</el-button><el-button size="small" :disabled="i === draft.steps.length - 1" @click="moveStep(i, 1)">下移</el-button><el-button size="small" type="danger" text @click="removeStep(i)">移除步骤</el-button></div>
                  </div>
                </el-collapse-item>
              </el-collapse>
              <el-button class="add-step" plain @click="addStep">＋ 添加步骤</el-button>
              <div class="section-title"><h2>默认变量</h2><el-button text @click="addVariable">添加变量</el-button></div><p class="field-help">这里保存通用测试数据。手机号、验证码等在执行时临时填写，不必保存在用例中。</p>
              <div v-for="(item, i) in variableRows" :key="i" class="variable-row"><el-input v-model="item.key" placeholder="变量名，如 comment" /><el-input v-model="item.value" placeholder="默认值" /><el-button text type="danger" @click="variableRows.splice(i,1)">移除</el-button></div>
            </el-form>
            <footer class="save-bar"><span>{{ draft.platform === 'ANDROID' ? '已在安卓真机验证定位链路' : '此平台尚未完成本模块真机验证' }}</span><el-button type="primary" :loading="saving" :disabled="!canWrite" @click="save">保存用例</el-button></footer>
          </section>
          <aside class="execution-panel">
            <h2>在设备上运行</h2><p class="field-help">应用需已安装并登录。示例会先返回主导航，再执行测试。</p>
            <el-select v-model="deviceId" placeholder="选择已连接设备" class="device-select" clearable><el-option v-for="device in matchingDevices" :key="device.id" :value="device.id" :label="`${device.name || device.id} · ${device.version || platformName(device.platform)}`" :disabled="device.status !== 'CONNECTED' || device.disabled" /></el-select>
            <p v-if="!matchingDevices.length" class="field-help">当前没有此平台的设备，请先到设备池连接。</p>
            <el-button class="inspect-button" :loading="inspecting" :disabled="!deviceId || !canWrite || executing" @click="inspect">读取当前页面</el-button>
            <div class="divider" /><h3>本次执行变量</h3><p class="field-help">可覆盖默认变量；只用于本次执行。</p>
            <div v-for="item in executionVars" :key="item" class="run-variable"><label>{{ item }}</label><el-input v-model="runVariables[item]" :type="/phone|code|password|token/i.test(item) ? 'password' : 'text'" :show-password="/phone|code|password|token/i.test(item)" placeholder="留空使用默认值" /></div>
            <el-checkbox v-if="hasWrites" v-model="allowWrites">允许本次发布或修改业务数据</el-checkbox>
            <el-button type="primary" class="run-button" :loading="executing" :disabled="!canWrite || !deviceId || (hasWrites && !allowWrites)" @click="execute">保存并执行</el-button>
            <p class="execution-note">重复目标会停止并提示。发布操作不自动重试。</p>
            <div v-if="latestRun" class="latest-run"><div class="section-title"><h3>最近执行</h3><el-tag :type="statusType(latestRun.status)">{{ statusLabel(latestRun.status) }}</el-tag></div><p>{{ latestRun.message }}</p><el-button text type="primary" @click="openRun(latestRun)">查看步骤和截图</el-button></div>
          </aside>
        </div>
      </el-tab-pane>
      <el-tab-pane label="执行记录" name="runs"><el-table :data="runs" empty-text="尚无执行记录。先保存一条用例并选择设备运行。" @row-click="openRun"><el-table-column prop="scriptName" label="用例" min-width="220" /><el-table-column prop="deviceId" label="设备" min-width="170" /><el-table-column label="状态" width="130"><template #default="{ row }"><el-tag :type="statusType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column prop="message" label="结果" min-width="220" /><el-table-column label="开始时间" width="190"><template #default="{ row }">{{ when(row.startedAt) }}</template></el-table-column><el-table-column width="90"><template #default="{ row }"><el-button text type="primary" @click.stop="openRun(row)">查看</el-button></template></el-table-column></el-table></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="importVisible" title="导入自动化脚本" width="min(800px, 94vw)"><p class="field-help">粘贴生成的 JSON 用例。脚本只支持页面操作，不执行系统命令。导入会创建新副本。</p><el-input v-model="importText" type="textarea" :rows="18" aria-label="脚本 JSON" /><template #footer><el-button @click="importVisible = false">取消</el-button><el-button type="primary" @click="importScript">载入编辑器</el-button></template></el-dialog>
    <el-drawer v-model="runVisible" title="执行详情" size="min(1050px, 96vw)"><template v-if="selectedRun"><div class="detail-header"><h2>{{ selectedRun.scriptName }}</h2><el-tag :type="statusType(selectedRun.status)">{{ statusLabel(selectedRun.status) }}</el-tag></div><p>{{ selectedRun.message }}</p><p class="field-help">{{ selectedRun.deviceId }} · {{ when(selectedRun.startedAt) }}</p><el-button v-if="active(selectedRun.status) && canWrite" :loading="cancelling" @click="cancelRun">停止执行</el-button><el-table :data="selectedRun.events" empty-text="正在连接设备，首个步骤完成后显示结果。"><el-table-column prop="index" label="步骤" width="60" /><el-table-column prop="name" label="操作" min-width="150" /><el-table-column label="状态" width="100"><template #default="{ row }"><el-tag :type="statusType(row.status)">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column prop="message" label="说明" min-width="190" /><el-table-column label="耗时" width="90"><template #default="{ row }">{{ (row.durationMs/1000).toFixed(1) }}s</template></el-table-column><el-table-column width="90"><template #default="{ row }"><el-button text @click="showEvidence(row.evidence)">查看现场</el-button></template></el-table-column></el-table></template></el-drawer>
    <el-drawer v-model="snapshotVisible" :title="snapshotTitle" size="min(1250px, 98vw)"><div v-loading="evidenceLoading"><template v-if="snapshot"><el-alert v-if="snapshot.warning" :title="snapshot.warning" type="warning" :closable="false" /><div class="snapshot-layout"><div><el-image v-if="snapshot.image" :src="snapshot.image" fit="contain" :preview-src-list="[snapshot.image]" class="device-shot" /><p v-else>没有截图</p></div><div><el-input v-model="nodeSearch" placeholder="搜索文字、ID 或控件类型" clearable /><el-table :data="visibleNodes" height="65vh" empty-text="没有可见控件"><el-table-column prop="text" label="文字" min-width="140" /><el-table-column prop="id" label="ID" min-width="150" show-overflow-tooltip /><el-table-column prop="type" label="类型" width="140" show-overflow-tooltip /><el-table-column width="110"><template #default="{ row }"><el-button text type="primary" :disabled="!canWrite" @click="addFromNode(row)">添加点击</el-button></template></el-table-column></el-table><el-collapse><el-collapse-item title="查看原始页面结构"><pre class="raw-source">{{ snapshot.source }}</pre></el-collapse-item></el-collapse></div></div></template></div></el-drawer>
    <el-dialog v-model="helpVisible" title="如何使用" width="min(720px, 94vw)"><div class="help-copy"><p>先载入示例或导入生成的脚本，编辑步骤后选择设备执行。新模块独立保存用例与报告，不写入原有元素库。</p><p>“读取当前页面”能查看实时控件结构，也能从控件直接添加点击步骤。有重复文字时，可增加区域限制、控件 ID 或明确匹配序号。</p><p>当前版本执行结构化脚本，不会自动把任意一句话转换成测试。你可以把测试目标和页面快照交给助手，生成脚本后导入。</p><p>H5 优先使用页面暴露的无障碍结构；没有暴露的内容会明确失败。本版不自动切换 WebView、不用图片猜测坐标。</p><p>示例“CS赛事资讯评论草稿”会选择列表首条资讯，适用于跳转赛事详情的资讯。不同详情页需要相应步骤；默认只填草稿，不发布。</p><p>Android、iOS、原生鸿蒙共用脚本格式，定位规则按实际控件调整。本模块已验证安卓链路；iOS 和鸿蒙需要连接设备验收。</p><p>独立 Appium 默认端口 {{ config?.appiumPort || 14731 }}，仅在执行或读取页面时启动。端口被其他服务占用时会报错，不会停止其他进程。用例和证据保存在当前执行节点。</p></div></el-dialog>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { apiClient } from '../api'
import { canWrite } from '../stores/auth'
interface Target { text?:string; contains?:string; id?:string; description?:string; role?:string; withinText?:string; index?:number|null }
interface Step { name:string; action:string; target?:Target|null; value?:string|null; saveAs?:string|null; timeoutSeconds?:number; direction?:string; effect?:string }
interface Script { id?:string|null; name:string; platform:string; packageName?:string; variables:Record<string,string>; steps:Step[]; updatedAt?:string|null }
interface Event { index:number; name:string; action:string; status:string; message:string; evidence:string; durationMs:number }
interface Run { id:string; scriptName:string; deviceId:string; status:string; message:string; startedAt:string; events:Event[] }
interface UiNode { path:string; text:string; id:string; description:string; type:string; editable:boolean; left:number; top:number; right:number; bottom:number }
interface Evidence { source:string; nodes:UiNode[]; image?:string; warning?:string }
const actions:Record<string,string>={LAUNCH:'启动应用',CLICK:'点击',INPUT:'输入',WAIT:'等待目标',ASSERT:'检查内容',READ:'读取为变量',BACK:'返回',BACK_TO:'返回直到目标出现',SWIPE:'滑动',SNAPSHOT:'保存页面现场'}
const statuses:Record<string,string>={QUEUED:'等待执行',RUNNING:'执行中',CANCELLING:'正在停止',CANCELLED:'已停止',SUCCEEDED:'全部通过',PASSED:'通过',FAILED:'失败',INTERRUPTED:'执行中断'}
const blank=():Script=>({name:'',platform:'ANDROID',packageName:'com.pwrd.steam.esports',variables:{},steps:[{name:'读取当前页面',action:'SNAPSHOT',effect:'READ'}]})
const draft=ref<Script>(blank()),scripts=ref<Script[]>([]),templates=ref<Script[]>([]),runs=ref<Run[]>([]),devices=ref<any[]>([]),config=ref<any>(null)
const variableRows=ref<{key:string;value:string}[]>([]),runVariables=ref<Record<string,string>>({}),savedState=ref('')
const tab=ref('scripts'),search=ref(''),expanded=ref('0'),deviceId=ref(''),error=ref(''),loading=ref(false),saving=ref(false),executing=ref(false),inspecting=ref(false),allowWrites=ref(false)
const importVisible=ref(false),importText=ref(''),helpVisible=ref(false),runVisible=ref(false),selectedRun=ref<Run|null>(null),latestRun=ref<Run|null>(null),cancelling=ref(false)
const snapshotVisible=ref(false),snapshotTitle=ref('当前页面'),snapshot=ref<Evidence|null>(null),evidenceLoading=ref(false),nodeSearch=ref('')
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v))
const request=<T,>(path:string,body?:unknown)=>apiClient.smartApp<T>(path,body===undefined?{}:{method:'POST',body:JSON.stringify(body)})
const serialized=()=>JSON.stringify({...draft.value,variables:Object.fromEntries(variableRows.value.filter(v=>v.key.trim()).map(v=>[v.key.trim(),v.value]))})
const dirty=computed(()=>serialized()!==savedState.value)
const filteredScripts=computed(()=>scripts.value.filter(s=>s.name.toLowerCase().includes(search.value.toLowerCase())))
const matchingDevices=computed(()=>devices.value.filter(d=>d.platform===draft.value.platform||(draft.value.platform==='ANDROID'&&d.platform==='POG_ANDROID')||(draft.value.platform==='IOS'&&d.platform==='POG_IOS')))
const hasWrites=computed(()=>draft.value.steps.some(s=>s.effect==='WRITE'||s.action==='CLICK'&&['发布','发送','删除','确认支付'].includes(s.target?.text||'')))
const executionVars=computed(()=>{
  const all=new Set(variableRows.value.map(v=>v.key.trim()).filter(Boolean)),produced=new Set<string>()
  for(const s of draft.value.steps){for(const m of JSON.stringify(s).matchAll(/\$\{([A-Za-z][A-Za-z0-9_]*)\}/g))if(!produced.has(m[1]))all.add(m[1]);if(s.action==='READ'&&s.saveAs)produced.add(s.saveAs)}
  return [...all]
})
const visibleNodes=computed(()=>snapshot.value?.nodes.filter(n=>(n.text||n.id||n.editable)&&`${n.text} ${n.id} ${n.type}`.toLowerCase().includes(nodeSearch.value.toLowerCase()))||[])
const active=(s:string)=>['QUEUED','RUNNING','CANCELLING'].includes(s)
const statusLabel=(s:string)=>statuses[s]||s
const statusType=(s:string):'success'|'danger'|'warning'|'info'=>['PASSED','SUCCEEDED'].includes(s)?'success':s==='FAILED'?'danger':['CANCELLED','INTERRUPTED'].includes(s)?'warning':'info'
const platformName=(p:string)=>({ANDROID:'Android',IOS:'iOS',HARMONYOS:'鸿蒙'}[p]||p)
const when=(s:string)=>s?new Date(s).toLocaleString():'—'
const actionLabel=(s:string)=>actions[s]||s
const needsTarget=(s:string)=>['CLICK','INPUT','WAIT','ASSERT','READ','BACK_TO'].includes(s)
function targetKind(s:Step){const t=s.target||{};return t.text!=null?'text':t.contains!=null?'contains':t.id!=null?'id':t.description!=null?'description':t.role==='input'?'input':'text'}
function targetValue(s:Step){const k=targetKind(s);return k==='input'?'':String((s.target as any)?.[k]??'')}
function setTargetIndex(s:Step,value:string){if(!s.target)s.target={};if(value===''){delete s.target.index;return}const n=Number(value);if(Number.isInteger(n)&&n>=0&&n<=1000)s.target.index=n}
function targetSummary(s:Step){return needsTarget(s.action)?targetKind(s)==='input'?'当前输入框':targetValue(s):s.action==='SWIPE'?(s.direction==='DOWN'?'向下':'向上'):s.action==='LAUNCH'?(s.value||draft.value.packageName||''):''}
function setTargetKind(s:Step,k:string){s.target=k==='input'?{role:'input'}:{[k]:''}}
function setTargetValue(s:Step,v:string){if(!s.target)s.target={};(s.target as any)[targetKind(s)]=v}
function onActionChange(s:Step){if(needsTarget(s.action)&&!s.target)s.target=s.action==='INPUT'?{role:'input'}:{text:''};if(s.action==='SWIPE')s.direction='UP'}
function loadDraft(s:Script){draft.value=clone(s);variableRows.value=Object.entries(s.variables||{}).map(([key,value])=>({key,value}));runVariables.value={};allowWrites.value=false;expanded.value='0';savedState.value=serialized()}
async function discardChanges(){if(!dirty.value)return true;try{await ElMessageBox.confirm('当前修改还没有保存，是否切换用例？','切换用例',{confirmButtonText:'切换',cancelButtonText:'继续编辑'});return true}catch{return false}}
async function selectScript(s:Script){if(await discardChanges())loadDraft(s)}
async function newScript(){if(await discardChanges())loadDraft(blank())}
async function useTemplate(i:number){if(await discardChanges())loadDraft({...clone(templates.value[i]),id:null})}
function duplicate(){draft.value.id=null;draft.value.name+='（副本）'}
function addStep(){draft.value.steps.push({name:'',action:'CLICK',target:{text:''},timeoutSeconds:10,effect:'READ'});expanded.value=String(draft.value.steps.length-1)}
function moveStep(i:number,d:number){const steps=draft.value.steps;[steps[i],steps[i+d]]=[steps[i+d],steps[i]];expanded.value=String(i+d)}
function removeStep(i:number){draft.value.steps.splice(i,1);expanded.value=''}
function addVariable(){variableRows.value.push({key:'',value:''})}
async function load(){loading.value=true;error.value='';try{const [s,t,r,d,c]=await Promise.all([request<Script[]>('/scripts'),request<Script[]>('/templates'),request<Run[]>('/runs'),apiClient.getDevices(),request<any>('/config')]);scripts.value=s;templates.value=t;runs.value=r;devices.value=d;config.value=c}catch(e:any){error.value=e.message||'读取失败'}finally{loading.value=false}}
async function save():Promise<Script|null>{
  if(!canWrite.value)return null
  if(variableRows.value.some(v=>!v.key.trim()||!/^[A-Za-z][A-Za-z0-9_]*$/.test(v.key.trim()))) {ElMessage.warning('请填写英文变量名');return null}
  if(new Set(variableRows.value.map(v=>v.key.trim())).size!==variableRows.value.length){ElMessage.warning('变量名不能重复');return null}
  saving.value=true
  try{const value=JSON.parse(serialized());for(const s of value.steps){if(s.target?.index==null)delete s.target?.index;if(s.value==='')s.value=s.action==='INPUT'?'':null}const saved=await request<Script>('/scripts',value);draft.value=saved;savedState.value=serialized();scripts.value=await request<Script[]>('/scripts');ElMessage.success('用例已保存');return saved}catch(e:any){ElMessage.error(e.message||'保存失败');return null}finally{saving.value=false}
}
function exportScript(){const blob=new Blob([JSON.stringify(JSON.parse(serialized()),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${draft.value.name||'app-case'}.json`;a.click();URL.revokeObjectURL(url)}
async function importScript(){try{if(importText.value.length>500000)throw new Error('脚本不能超过 500KB');const s=JSON.parse(importText.value);if(!s||!s.name||!['ANDROID','IOS','HARMONYOS'].includes(s.platform)||!Array.isArray(s.steps)||s.steps.length===0||s.steps.length>100||s.steps.some((st:any)=>!st||typeof st!=='object'||!actions[st.action]))throw new Error('需要有效的名称、平台和 1–100 个受支持的步骤');if(!await discardChanges())return;loadDraft({...s,id:null,variables:s.variables||{}});savedState.value='';importVisible.value=false;ElMessage.success('已载入，请检查后保存')}catch(e:any){ElMessage.error(e.message||'脚本格式不正确')}}
async function inspect(){inspecting.value=true;try{snapshot.value=await request<Evidence>('/inspect',{deviceId:deviceId.value});nodeSearch.value='';snapshotTitle.value='设备当前页面';snapshotVisible.value=true}catch(e:any){ElMessage.error(e.message)}finally{inspecting.value=false}}
function addFromNode(n:UiNode){if(!canWrite.value)return;const target:Target=n.id?{id:n.id}:n.text?{text:n.text}:{description:n.description};if(!n.id&&!n.text&&!n.description)return ElMessage.warning('此控件没有可定位属性');draft.value.steps.push({name:`点击${n.text||n.id||n.description}`,action:'CLICK',target,timeoutSeconds:10,effect:'READ'});expanded.value=String(draft.value.steps.length-1);ElMessage.success('已添加到用例末尾')}
async function execute(){executing.value=true;try{const s=await save();if(!s?.id)return;const vars=Object.fromEntries(Object.entries(runVariables.value).filter(([k,v])=>executionVars.value.includes(k)&&v!==''));const r=await request<Run>(`/scripts/${s.id}/runs`,{deviceId:deviceId.value,variables:vars,allowWrites:allowWrites.value});latestRun.value=r;selectedRun.value=r;runVisible.value=true;runs.value=await request<Run[]>('/runs')}catch(e:any){ElMessage.error(e.message||'执行失败')}finally{executing.value=false}}
async function openRun(r:Run){try{selectedRun.value=await request<Run>(`/runs/${r.id}`);runVisible.value=true}catch(e:any){ElMessage.error(e.message)}}
async function cancelRun(){if(!selectedRun.value)return;cancelling.value=true;try{selectedRun.value=await request<Run>(`/runs/${selectedRun.value.id}/cancel`,{});}catch(e:any){ElMessage.error(e.message)}finally{cancelling.value=false}}
async function showEvidence(name:string){if(!selectedRun.value)return;snapshotTitle.value='步骤执行现场';snapshotVisible.value=true;snapshot.value=null;evidenceLoading.value=true;try{snapshot.value=await request<Evidence>(`/runs/${selectedRun.value.id}/evidence/${name}`);nodeSearch.value=''}catch(e:any){ElMessage.error(e.message)}finally{evidenceLoading.value=false}}
let timer:ReturnType<typeof setInterval>|undefined,polling=false,disposed=false
async function poll(){if(polling||disposed)return;const id=selectedRun.value&&active(selectedRun.value.status)?selectedRun.value.id:latestRun.value&&active(latestRun.value.status)?latestRun.value.id:null;if(!id)return;polling=true;try{const r=await request<Run>(`/runs/${id}`);if(disposed)return;if(selectedRun.value?.id===id)selectedRun.value=r;if(latestRun.value?.id===id)latestRun.value=r;if(!active(r.status))runs.value=await request<Run[]>('/runs')}catch(e:any){if(!disposed)error.value=e.message||'执行状态读取失败'}finally{polling=false}}
onMounted(()=>{savedState.value=serialized();load();timer=setInterval(poll,1800)})
onUnmounted(()=>{disposed=true;if(timer)clearInterval(timer)})
</script>

